const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  try {
    // 1. Geometry & Time Definitions
    const paradise = ee.Geometry.Point([-121.6219, 39.7596]);
    const searchArea = paradise.buffer(10000); // 10km buffer around Paradise
    const startDate = '2018-11-07';
    const endDate = '2018-11-10';

    // 2. Data Acquisition - VIIRS Active Fire data
    let fireCollection = ee.ImageCollection('NOAA/VIIRS/001/VNP14IMGML')
      .filterDate(startDate, endDate)
      .filterBounds(searchArea);

    // Check if collection is empty
    const collectionSize = await fireCollection.size().getInfo();
    if (collectionSize === 0) {
      print("No VIIRS fire data found for the date range.");
      print("<answer>C1</answer>");
      return;
    }

    print(`VIIRS images found: ${collectionSize}`);

    // 3. Processing - Filter for high confidence fires and count pixels
    // Confidence values: 0=not processed, 1-4=low, 5-8=nominal, 9=high
    const highConfidenceFires = fireCollection.filter(ee.Filter.gte('Confidence', 7));

    // Count fire pixels in the region
    const fireCountImage = highConfidenceFires.select('Confidence').reduce(ee.Reducer.count());

    const fireStats = await fireCountImage.reduceRegion({
      reducer: ee.Reducer.sum(),
      geometry: searchArea,
      scale: 1000,
      maxPixels: 1e9
    }).getInfo();

    const totalFirePixels = fireStats.Confidence || 0;

    print(`High confidence fire pixels: ${totalFirePixels}`);
    print(`Search area radius: 10km around Paradise, CA`);

    // 4. Validation & Final Answer
    if (totalFirePixels === 0) {
      print("<answer>B</answer>");
    } else if (totalFirePixels > 0) {
      print("<answer>A</answer>");
    } else {
      print("<answer>C3</answer>");
    }

  } catch (error) {
    print(`Error: ${error}`);
    print("<answer>D</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
